221: function createPlayerData(stage) {
222:   const st = STAGES[stage];
223:   return {
224:     x: 500, y: pathY(500), vx: 0, vy: 0, angle: 0, r: st.r, stage,
225:     hp: st.hp, maxHp: st.hp, hunger: 70, thirst: 62, walk: 0,
226:     biteT: 0, hurtT: 0, dashT: 0, dashCd: 0, attackCd: 0.2,
227:   };
228: }
