230: function setStage(stage, heal = true) {
231:   game.stage = stage;
232:   const st = STAGES[stage];
233:   const p = game.player;
234:   if (!p) return;
235:   p.stage = stage;
236:   p.r = st.r;
237:   p.maxHp = st.hp;
238:   if (heal) p.hp = st.hp;
239:   p.hp = Math.min(p.hp, st.hp);
240: }
