242: function randomZonePoint(zone, nearPath = true) {
243:   const spread = nearPath ? 520 : 700;
244:   let x = between(Math.random, zone.x0 + 120, zone.x1 - 120);
245:   let y = clamp(pathY(x) + between(Math.random, -spread, spread), 80, WORLD_H - 80);
246:   // keep plants and bugs out of the water
247:   for (let tries = 0; tries < 14; tries++) {
248:     let wet = false;
249:     for (const pd of game.puddles) {
250:       const ex = (x - pd.x) / (pd.rx * 1.18);
251:       const ey = (y - pd.y) / (pd.ry * 1.35);
252:       if (ex * ex + ey * ey < 1) { wet = true; break; }
253:     }
254:     if (!wet) break;
255:     x = between(Math.random, zone.x0 + 120, zone.x1 - 120);
256:     y = clamp(pathY(x) + between(Math.random, -spread, spread), 80, WORLD_H - 80);
257:   }
258:   return { x, y };
259: }
