261: function makePuddles(zi) {
262:   const zone = ZONES[zi];
263:   const rnd = mulberry32(4400 + zi * 733);
264:   const P = PALETTES[zone.palette];
265:   for (let i = 0; i < zone.puddles; i++) {
266:     const x = zone.x0 + 140 + ((i + 0.5) / zone.puddles) * (zone.x1 - zone.x0 - 280) + between(rnd, -70, 70);
267:     // leave the sleeping queen's clearing dry
268:     if (zi === 3 && Math.abs(x - 6780) < 220) continue;
269:     const y = pathY(x) + between(rnd, -95, 95);
270:     const rx = between(rnd, 46, 80);
271:     const ry = between(rnd, 26, 41);
272:     game.puddles.push({
273:       x, y, rx, ry, rot: between(rnd, -0.25, 0.25), seed: rnd() * 9,
274:       palette: P, drinking: false, ripples: rnd() * 4,
275:     });
276:   }
277: }
