372:       phase: Math.random() * TAU,
373:       speed: between(Math.random, 0.2, 1),
374:       size: between(Math.random, 0.7, 2.1),
375:       kind: kind === 'edge' || kind === 'deep'
376:         ? (Math.random() > 0.45 ? 'firefly' : 'spore')
377:         : (Math.random() > 0.6 ? 'fluff' : 'pollen'),
378:       depth: between(Math.random, 0.4, 1.2),
379:     });
380:   }
