473: // ————————————————————————————————————————————————
474: // update — playing
475: // ————————————————————————————————————————————————
476: 
477: function updatePlaying(dt) {
478:   const slow = game.slowmo > 0 ? 0.38 : 1;
479:   const sdt = dt * slow;
480:   game.time += sdt;
481:   game.playTime += dt;
482:   game.slowmo = Math.max(0, game.slowmo - dt);
483: 
484:   updatePlayer(sdt);
485:   updateFlowers(sdt);
486:   for (const c of game.mobs) updateMob(c, sdt);
487:   resolveHazards(sdt);
488:   updateCombat(sdt);
489:   updateParticles(sdt);
490:   updateTexts(sdt);
491:   updateMotes(sdt);
492:   updateCamera(dt);
493:   updateTimers(dt);
494:   sound.update(dt, ZONES[game.zoneIndex].id, game.state === 'playing');
495: 
496:   if (game.state !== 'playing') return;
497:   if (game.winTimer > 0) {
498:     game.winTimer -= dt;
499:     if (game.winTimer <= 0) showWin();
500:   }
501: }
502: 
503: function updatePlayer(dt) {
504:   const p = game.player;
505:   const st = STAGES[game.stage];
506:   p.attackCd -= dt;
507:   p.hurtT = Math.max(0, p.hurtT - dt);
508:   p.dashT = Math.max(0, p.dashT - dt);
509:   p.dashCd = Math.max(0, p.dashCd - dt);
510:   p.biteT = Math.max(0, p.biteT - dt);
511:   game.toughCd = Math.max(0, game.toughCd - dt);
512:   game.flowerCd = Math.max(0, game.flowerCd - dt);
513: 
514:   const inp = inputVector();
515:   if (dashQueued) {
516:     dashQueued = false;
517:     if (st.dash && p.dashCd <= 0) {
518:       // dash toward the stick/key direction, or straight ahead when standing still
519:       let dx = inp.x, dy = inp.y;
520:       if (inp.mag <= 0.12) {
521:         dx = Math.cos(p.angle);
522:         dy = Math.sin(p.angle);
523:       }
524:       const l = Math.hypot(dx, dy) || 1;
525:       p.dashVX = (dx / l) * st.speed * 2.8;
526:       p.dashVY = (dy / l) * st.speed * 2.8;
527:       p.dashT = 0.17;
528:       p.dashCd = 0.55;
529:       p.angle = Math.atan2(dy, dx);
530:       sound.dash();
531:       for (let i = 0; i < 7; i++) {
532:         burst(p.x - dx * 10, p.y - dy * 10, '#c9c6a4', 1, {
533:           speed: 40, life: 0.5, size: 2.4, type: 'dust',
534:         });
535:       }
536:       game.shake = Math.max(game.shake, 1.5);
537:     }
538:   }
539: 
540:   let speed = st.speed;
541:   const pathDist = Math.abs(p.y - pathY(p.x));
542:   if (game.zoneIndex >= 2 && pathDist > 300) speed *= 0.84;
543:   if (game.drinking) speed *= 0.94;
544: 
545:   if (p.dashT > 0) {
546:     p.vx = p.dashVX;
547:     p.vy = p.dashVY;
548:   } else {
549:     const targetVX = inp.x * speed * inp.mag;
550:     const targetVY = inp.y * speed * inp.mag;
551:     const k = 1 - Math.exp(-dt * (inp.mag > 0 ? 10 : 7));
552:     p.vx = lerp(p.vx, targetVX, k);
553:     p.vy = lerp(p.vy, targetVY, k);
554:   }
555: 
556:   p.x += p.vx * dt;
557:   p.y += p.vy * dt;
558:   p.x = clamp(p.x, 26, WORLD_W - 26);
559:   p.y = clamp(p.y, 52, WORLD_H - 52);
560: 
561:   // zone gates
562:   game.blocked = false;
563:   for (const b of BARRIERS) {
564:     if (game.stage < b.require) {
565:       if (p.x > b.x - 30) {
566:         p.x = b.x - 30;
567:         p.vx = Math.min(0, p.vx);
568:       }
569:       // latch the hint while the player is pressed against the thicket
570:       if (p.x >= b.x - 36) game.blocked = true;
571:     }
572:   }
573: 
574:   const sp = Math.hypot(p.vx, p.vy);
575:   if (sp > 20) {
576:     p.angle = lerpAngle(p.angle, Math.atan2(p.vy, p.vx), 1 - Math.exp(-dt * 12));
577:     p.walk += dt * (5 + sp * 0.07);
578:   } else {
579:     p.walk += dt * 1.1;
580:   }
581: 
582:   // water
583:   game.drinking = false;
584:   for (const pd of game.puddles) {
585:     pd.drinking = false;
586:     const ex = (p.x - pd.x) / pd.rx;
587:     const ey = (p.y - pd.y) / pd.ry;
588:     if (ex * ex + ey * ey < 1 && p.thirst < 99.99) {
589:       pd.drinking = true;
590:       game.drinking = true;
591:       p.thirst = Math.min(100, p.thirst + 52 * dt);
592:       game.splashCd -= dt;
593:       if (game.splashCd <= 0) {
594:         game.splashCd = 0.34;
595:         burst(p.x, p.y + 2, '#cfe3d8', 3, { speed: 22, life: 0.6, size: 1.8, type: 'drop', gravity: 20 });
596:         if (Math.random() > 0.5) sound.drink();
597:       }
598:     }
599:   }
600: 
601:   // tiny bites of nectar
602:   for (const f of game.flowers) {
603:     if (f.nectar <= 0) continue;
604:     if (dist2(p.x, p.y, f.x, f.y) < (p.r + f.r + 7) ** 2 && game.flowerCd <= 0) {
605:       f.nectar = 0;
606:       f.respawn = between(Math.random, FLOWER_RESPAWN[0], FLOWER_RESPAWN[1]);
607:       p.hunger = Math.min(100, p.hunger + 4);
608:       p.thirst = Math.min(100, p.thirst + 6);
609:       game.biomass += 1;
610:       game.flowerCd = 0.3;
611:       addText(f.x, f.y - 12, '+nectar', '#6d6a3f', 12);
612:       burst(f.x, f.y, f.heart, 8, { speed: 55, life: 0.8, size: 2.2, type: 'dot', gravity: 10 });
613:     }
614:   }
615: 
616:   // vitals
617:   p.hunger = clamp(p.hunger - st.hungerDrain * dt, 0, 100);
618:   p.thirst = clamp(p.thirst - st.thirstDrain * dt, 0, 100);
619:   if (p.hunger <= 0) p.hp -= 1.5 * dt;
620:   if (p.thirst <= 0) p.hp -= 2.2 * dt;
621:   if (p.hunger > 35 && p.thirst > 35) p.hp = Math.min(p.maxHp, p.hp + 1.0 * dt);
622:   p.hp = Math.min(p.hp, p.maxHp);
623:   if (p.hp <= 0 && game.state === 'playing') die();
624: 
625:   // zone change
626:   const zi = zoneIndexAt(p.x);
627:   if (zi !== game.zoneIndex) {
628:     game.zoneIndex = zi;
629:     seedMotes();
630:     enterZone(ZONES[zi]);
631:     sound.setZone(ZONES[zi].id);
632:     if (zi === 3 && game.stage >= 4 && !game.bossDead && !game.bossIntro) {
633:       game.bossIntro = true;
634:       flash('Something enormous is breathing in the roots.', 4200);
635:     }
636:   }
637: }
638: 
639: function updateFlowers(dt) {
640:   for (const f of game.flowers) {
641:     if (f.nectar <= 0) {
642:       f.respawn -= dt;
643:       if (f.respawn <= 0) {
644:         f.nectar = 1;
645:         burst(f.x, f.y, f.heart, 5, { speed: 22, life: 1.2, size: 1.4, type: 'dot' });
646:       }
647:     }
648:   }
649: }
650: 
651: function updateMob(c, dt) {
652:   if (!c.alive) {
653:     if (c.respawn > 0) {
654:       c.respawn -= dt;
655:       if (c.respawn <= 0) respawnMob(c);
656:     }
657:     return;
658:   }
659:   if (c.boss) { updateBoss(c, dt); return; }
660: 
661:   const p = game.player;
662:   const dx = p.x - c.x, dy = p.y - c.y;
663:   const d = Math.hypot(dx, dy) || 1;
664:   c.attackCd = Math.max(0, c.attackCd - dt);
665:   c.fleeT -= dt;
666:   c.restT -= dt;
667: 
668:   const canEat = game.stage >= c.def.tier;
669:   const dangerous = c.def.threat > 0 && game.stage <= c.def.tier;
670:   let ax = 0, ay = 0;
671:   let speed = c.def.speed;
672: 
673:   if (dangerous && d < c.def.aggro) {
674:     c.aggro = true;
675:     ax = dx / d;
676:     ay = dy / d;
677:     const weave = Math.sin(game.time * 2.6 + c.seed) * 0.32;
678:     ax += -dy / d * weave;
679:     ay += dx / d * weave;
680:     speed = c.def.speed * 1.1;
681:   } else if (canEat && d < 300) {
682:     c.aggro = false;
683:     if (c.fleeT <= 0 && c.restT <= 0) {
684:       c.fleeT = 0.62;
685:       c.restT = 1.0 + Math.random() * 0.7;
686:     }
687:     if (c.fleeT > 0) {
688:       ax = -dx / d;
689:       ay = -dy / d;
690:       speed = c.def.burst;
691:     }
692:   } else {
693:     c.aggro = false;
694:   }
695: 
696:   if (!ax && !ay) {
697:     const wa = c.seed * 1.7 + game.time * 0.55;
698:     ax = Math.cos(wa) * 0.4;
699:     ay = Math.sin(wa * 1.31) * 0.4;
700:     const hdx = c.homeX - c.x, hdy = c.homeY - c.y;
701:     const hd = Math.hypot(hdx, hdy) || 1;
702:     if (hd > 230) {
703:       ax += hdx / hd * 1.4;
704:       ay += hdy / hd * 1.4;
705:     }
706:   }
707: 
708:   const al = Math.hypot(ax, ay) || 1;
709:   const kv = 1 - Math.exp(-dt * (c.aggro ? 5 : 3.4));
710:   c.vx = lerp(c.vx, (ax / al) * speed, kv);
711:   c.vy = lerp(c.vy, (ay / al) * speed, kv);
712:   c.x += (c.vx + c.kvx) * dt;
713:   c.y += (c.vy + c.kvy) * dt;
714:   c.kvx *= Math.exp(-dt * 6);
715:   c.kvy *= Math.exp(-dt * 6);
716: 
717:   const zone = ZONES[c.zone];
718:   c.x = clamp(c.x, zone.x0 + 16, zone.x1 - 16);
719:   c.y = clamp(c.y, 48, WORLD_H - 48);
720: 
721:   const v = Math.hypot(c.vx, c.vy);
722:   if (v > 8) c.angle = lerpAngle(c.angle, Math.atan2(c.vy, c.vx), 1 - Math.exp(-dt * 8));
723:   c.walk += dt * (2 + v * 0.06);
724: }
725: 
726: function updateBoss(c, dt) {
727:   if (!c.alive) return;
728:   const p = game.player;
729:   const dx = p.x - c.x, dy = p.y - c.y;
730:   const d = Math.hypot(dx, dy) || 1;
731:   c.attackCd = Math.max(0, c.attackCd - dt);
732: 
733:   if (c.sleeping) {
734:     if (game.stage >= 4 && d < 620) {
735:       c.sleeping = false;
736:       c.waking = 1.3;
737:       c.aggro = true;
738:       c.state = 'idle';
739:       game.bossEngaged = true;
740:       game.shake = 9;
741:       sound.boss();
742:       flash('The Mantis Queen unfolds from the roots.', 4400);
743:       burst(c.x, c.y, '#d9c98d', 18, { speed: 120, life: 1.4, size: 2.5, type: 'dot' });
744:     } else {
745:       c.walk += dt * 0.4;
746:       return;
747:     }
748:   }
749: 
750:   if (c.waking > 0) {
751:     c.waking -= dt;
752:     c.vx *= Math.exp(-dt * 6);
753:     c.vy *= Math.exp(-dt * 6);
754:     c.x += c.vx * dt;
755:     c.y += c.vy * dt;
756:     return;
757:   }
758: 
759:   if (d > 1080) {
760:     c.aggro = false;
761:     game.bossEngaged = false;
762:     const hdx = c.homeX - c.x, hdy = c.homeY - c.y;
763:     const hd = Math.hypot(hdx, hdy) || 1;
764:     c.vx = lerp(c.vx, hdx / hd * 95, 1 - Math.exp(-dt * 3));
765:     c.vy = lerp(c.vy, hdy / hd * 95, 1 - Math.exp(-dt * 3));
766:     c.x += c.vx * dt;
767:     c.y += c.vy * dt;
768:     c.angle = lerpAngle(c.angle, Math.atan2(hdy, hdx), 1 - Math.exp(-dt * 6));
769:     c.walk += dt * 2;
770:     return;
771:   }
772: 
773:   c.aggro = true;
774:   game.bossEngaged = true;
775:   c.lungeCd -= dt;
776: 
777:   if (c.state === 'idle') {
778:     const weave = Math.sin(game.time * 1.7 + c.seed) * 0.6;
779:     let ax = dx / d - (dy / d) * weave;
780:     let ay = dy / d + (dx / d) * weave;
781:     const al = Math.hypot(ax, ay) || 1;
782:     c.vx = lerp(c.vx, (ax / al) * 152, 1 - Math.exp(-dt * 3.2));
783:     c.vy = lerp(c.vy, (ay / al) * 152, 1 - Math.exp(-dt * 3.2));
784:     if (d < 370 && c.lungeCd <= 0) {
785:       c.state = 'telegraph';
786:       c.tele = 0.62;
787:       c.vx *= 0.15;
788:       c.vy *= 0.15;
789:     }
790:   } else if (c.state === 'telegraph') {
791:     c.tele -= dt;
792:     c.vx *= Math.exp(-dt * 8);
793:     c.vy *= Math.exp(-dt * 8);
794:     if (c.tele <= 0) {
795:       c.state = 'lunge';
796:       c.lungeT = 0.37;
797:       c.lungeVX = (dx / d) * 660;
798:       c.lungeVY = (dy / d) * 660;
799:       game.shake = 7;
800:       sound.boss();
801:     }
802:   } else if (c.state === 'lunge') {
803:     c.lungeT -= dt;
804:     c.vx = c.lungeVX;
805:     c.vy = c.lungeVY;
806:     if (Math.random() > 0.7) {
807:       burst(c.x - c.vx * 0.02, c.y - c.vy * 0.02, '#c8bd92', 1, { speed: 20, life: 0.5, size: 2.4, type: 'dust' });
808:     }
809:     if (c.lungeT <= 0) {
810:       c.state = 'recover';
811:       c.recoverT = 0.85;
812:       c.lungeCd = 2.5 + Math.random() * 0.9;
813:     }
814:   } else {
815:     c.recoverT -= dt;
816:     c.vx *= Math.exp(-dt * 5);
817:     c.vy *= Math.exp(-dt * 5);
818:     if (c.recoverT <= 0) c.state = 'idle';
819:   }
820: 
821:   c.x += c.vx * dt;
822:   c.y += c.vy * dt;
823:   c.x = clamp(c.x, 5480, WORLD_W - 40);
824:   c.y = clamp(c.y, 80, WORLD_H - 80);
825: 
826:   const face = c.state === 'lunge' ? Math.atan2(c.vy, c.vx) : Math.atan2(dy, dx);
827:   c.angle = lerpAngle(c.angle, face, 1 - Math.exp(-dt * 7));
828:   c.walk += dt * (1.2 + Math.hypot(c.vx, c.vy) * 0.012);
829: }
