831: function respawnMob(c) {
832:   const zone = ZONES[c.zone];
833:   let pt = randomZonePoint(zone, true);
834:   for (let i = 0; i < 8 && dist(pt.x, pt.y, game.player.x, game.player.y) < 460; i++) {
835:     pt = randomZonePoint(zone, true);
836:   }
837:   c.x = pt.x; c.y = pt.y;
838:   c.homeX = pt.x; c.homeY = pt.y;
839:   c.vx = 0; c.vy = 0; c.kvx = 0; c.kvy = 0;
840:   c.hp = c.def.hp;
841:   c.alive = true;
842:   c.aggro = false;
843:   c.fleeT = 0; c.restT = 0;
844:   c.state = 'idle';
845: }
