851: function updateCombat(dt) {
852:   const p = game.player;
853:   if (p.attackCd > 0) return;
854:   let target = null;
855:   let best = Infinity;
856:   for (const c of game.mobs) {
857:     if (!c.alive || c.sleeping) continue;
858:     const reach = p.r + c.r + (c.boss ? 16 : 7);
859:     const d2 = dist2(p.x, p.y, c.x, c.y);
860:     if (d2 < reach * reach && d2 < best) { best = d2; target = c; }
861:   }
862:   if (!target) return;
863: 
864:   const edible = game.stage >= target.def.tier;
865:   if (!edible) {
866:     p.attackCd = 0.55;
867:     if (game.toughCd <= 0) {
868:       game.toughCd = 2.0;
869:       addText(target.x, target.y - target.r - 8, 'too tough', '#796a50', 13);
870:     }
871:     return;
872:   }
873: 
874:   p.attackCd = STAGES[game.stage].cadence;
875:   p.biteT = 0.16;
876:   const dmg = STAGES[game.stage].bite;
877:   target.hp -= dmg;
878:   const nx = (target.x - p.x) / (dist(p.x, p.y, target.x, target.y) || 1);
879:   const ny = (target.y - p.y) / (dist(p.x, p.y, target.x, target.y) || 1);
880:   target.kvx += nx * (target.boss ? 60 : 170);
881:   target.kvy += ny * (target.boss ? 60 : 170);
882:   target.hurtT = 0.15;
883:   if (target.boss && target.sleeping) wakeBoss(target);
884: 
885:   sound.bite();
886:   game.shake = Math.max(game.shake, target.boss ? 3 : 1.2);
887:   burst((p.x + target.x) / 2, (p.y + target.y) / 2, target.def.color, 5, {
888:     speed: 90, life: 0.4, size: 2.4, type: 'spark',
889:   });
890:   if (target.boss) addText(target.x, target.y - target.r - 12, `-${dmg}`, '#8f3f3a', 15);
891: 
892:   if (target.hp <= 0) killMob(target);
893: }
894: 
895: function killMob(c) {
896:   if (c.boss) {
897:     c.alive = false;
898:     c.aggro = false;
899:     game.bossDead = true;
900:     game.bossEngaged = false;
901:     game.slowmo = 2.6;
902:     game.winTimer = 2.8;
903:     game.shake = 12;
904:     sound.win();
905:     burst(c.x, c.y, '#d9c98d', 45, { speed: 180, life: 2.2, size: 3, type: 'spark' });
906:     burst(c.x, c.y, '#7d9b62', 30, { speed: 90, life: 2.6, size: 5, type: 'dot', gravity: -6 });
907:     addText(c.x, c.y - 50, 'the queen folds', '#4c5d3e', 20);
908:     return;
909:   }
910:   c.alive = false;
911:   c.respawn = c.def.respawn * between(Math.random, 0.75, 1.35);
912:   c.vx = 0; c.vy = 0;
913:   const p = game.player;
914:   game.biomass += c.def.biomass;
915:   game.eaten += 1;
916:   p.hunger = Math.min(100, p.hunger + c.def.hunger);
917:   p.thirst = Math.min(100, p.thirst + c.def.thirst);
918:   addText(c.x, c.y - c.r - 8, `+${c.def.biomass}`, '#6e6a3a', 16);
919:   burst(c.x, c.y, c.def.color, 10, { speed: 80, life: 0.9, size: 2.6, type: 'dot', gravity: 25 });
920:   burst(c.x, c.y, '#f0e7c8', 4, { speed: 30, life: 0.7, size: 3, type: 'ring' });
921:   sound.eat();
922:   if (game.stage < 4 && game.biomass >= MOLT_COST[game.stage] && game.nextMilestone !== game.stage) {
923:     game.nextMilestone = game.stage;
924:     flash('Your old skin feels tight. You are ready to molt.', 3400);
925:   }
926: }
927: 
928: function hurtPlayer(dmg, c) {
929:   const p = game.player;
930:   if (p.hurtT > 0 || game.state !== 'playing') return;
931:   p.hp -= dmg;
932:   p.hurtT = 0.82;
933:   game.hurtFlash = 0.65;
934:   game.shake = Math.max(game.shake, c.boss ? 8 : 4);
935:   sound.hurt();
936:   const a = Math.atan2(p.y - c.y, p.x - c.x);
937:   p.vx += Math.cos(a) * (c.boss ? 220 : 150);
938:   p.vy += Math.sin(a) * (c.boss ? 220 : 150);
939:   addText(p.x, p.y - p.r - 10, `-${Math.round(dmg)}`, '#8f3f3a', 15);
940:   burst(p.x, p.y, '#c07a62', 7, { speed: 70, life: 0.7, size: 2.4, type: 'dot' });
941:   if (p.hp <= 0) die();
942: }
943: 
944: function resolveHazards(dt) {
945:   const p = game.player;
946:   for (const c of game.mobs) {
947:     if (!c.alive || c.sleeping || !c.aggro) continue;
948:     if (c.def.threat <= 0) continue;
949:     const reach = p.r + c.r + 3;
950:     if (dist2(p.x, p.y, c.x, c.y) < reach * reach && p.hurtT <= 0) {
951:       let dmg = c.def.threat;
952:       if (c.boss) dmg = c.state === 'lunge' ? 26 : 15;
953:       hurtPlayer(dmg, c);
954:       if (game.state !== 'playing') break;
955:     }
956:   }
957: }
