959: function wakeBoss(c) {
960:   if (!c.sleeping) return;
961:   c.sleeping = false;
962:   c.waking = 1.0;
963:   c.aggro = true;
964:   game.bossEngaged = true;
965:   sound.boss();
966:   flash('The Mantis Queen unfolds from the roots.', 4000);
967: }
