969: function die() {
970:   if (game.state !== 'playing') return;
971:   const p = game.player;
972:   game.state = 'dead';
973:   document.body.classList.add('dead');
974:   p.hp = 0;
975:   game.biomass = Math.floor(game.biomass * 0.78);
976:   game.hurtFlash = 1.1;
977:   game.shake = 9;
978:   sound.death();
979:   burst(p.x, p.y, '#9c6b52', 24, { speed: 100, life: 1.8, size: 3.2, type: 'dot', gravity: 30 });
980:   setTimeout(() => { if (game.state === 'dead') showDeath(); }, 620);
981: }
