987: function burst(x, y, color, n, opts = {}) {
988:   const speed = opts.speed ?? 70;
989:   const life = opts.life ?? 0.8;
990:   const size = opts.size ?? 2.4;
991:   const type = opts.type ?? 'dot';
992:   const gravity = opts.gravity ?? 0;
993:   for (let i = 0; i < n; i++) {
994:     const a = Math.random() * TAU;
995:     const s = speed * (0.3 + Math.random() * 0.9);
996:     game.particles.push({
997:       x, y, vx: Math.cos(a) * s, vy: Math.sin(a) * s,
998:       life: life * (0.6 + Math.random() * 0.7), maxLife: life,
999:       size: size * (0.5 + Math.random() * 0.8), color, type,
1000:       rot: Math.random() * TAU, vr: between(Math.random, -6, 6), gravity,
1001:     });
1002:   }
1003:   if (game.particles.length > 420) game.particles.splice(0, game.particles.length - 420);
1004: }
1005: 
1006: function addText(x, y, text, color, size = 14) {
1007:   game.texts.push({ x, y, text, color, size, life: 1.5, maxLife: 1.5 });
1008:   if (game.texts.length > 30) game.texts.shift();
1009: }
1010: 
1011: function updateParticles(dt) {
1012:   for (let i = game.particles.length - 1; i >= 0; i--) {
1013:     const pt = game.particles[i];
1014:     pt.life -= dt;
1015:     if (pt.life <= 0) { game.particles.splice(i, 1); continue; }
1016:     pt.x += pt.vx * dt;
1017:     pt.y += pt.vy * dt;
1018:     pt.vy += pt.gravity * dt;
1019:     pt.vx *= Math.exp(-dt * 1.6);
1020:     pt.vy *= Math.exp(-dt * 1.6);
1021:     pt.rot += pt.vr * dt;
1022:     if (pt.type === 'ring') pt.size += dt * 42;
1023:   }
1024: }
1025: 
1026: function updateTexts(dt) {
1027:   for (let i = game.texts.length - 1; i >= 0; i--) {
1028:     const t = game.texts[i];
1029:     t.life -= dt;
1030:     t.y -= dt * 16;
1031:     if (t.life <= 0) game.texts.splice(i, 1);
1032:   }
1033: }
1034: 
1035: function updateMotes(dt) {
1036:   const cam = game.cam;
1037:   const halfW = view.w / (2 * cam.zoom) + 160;
1038:   const halfH = view.h / (2 * cam.zoom) + 160;
1039:   for (const m of game.motes) {
1040:     m.x += Math.cos(m.phase + game.time * 0.3) * dt * 9 * m.speed;
1041:     m.y += Math.sin(m.phase * 1.3 + game.time * 0.24) * dt * 7 * m.speed - dt * 2;
1042:     if (m.x < cam.x - halfW) m.x += halfW * 2;
1043:     if (m.x > cam.x + halfW) m.x -= halfW * 2;
1044:     if (m.y < cam.y - halfH) m.y += halfH * 2;
1045:     if (m.y > cam.y + halfH) m.y -= halfH * 2;
1046:   }
1047: }
1048: 
1049: function updateCamera(dt) {
1050:   if (!game.player) return;
1051:   const p = game.player;
1052:   const base = (view.w < 760 ? 1.0 : 1.16) - game.stage * 0.028;
1053:   const minZoom = Math.max(view.h / WORLD_H, view.w / WORLD_W) + 0.02;
1054:   const targetZoom = Math.max(base, minZoom);
1055:   game.cam.zoom = lerp(game.cam.zoom, targetZoom, 1 - Math.exp(-dt * 2.2));
1056:   const kx = 1 - Math.exp(-dt * 4.2);
1057:   const ky = 1 - Math.exp(-dt * 4.2);
1058:   game.cam.x = lerp(game.cam.x, p.x + p.vx * 0.16, kx);
1059:   game.cam.y = lerp(game.cam.y, p.y + p.vy * 0.1, ky);
1060:   clampCamera(false);
1061: 
1062:   game.shake *= Math.exp(-dt * 6.5);
1063:   if (game.shake < 0.08) game.shake = 0;
1064:   game.cam.sx = (Math.random() * 2 - 1) * game.shake;
1065:   game.cam.sy = (Math.random() * 2 - 1) * game.shake;
1066:   game.hurtFlash = Math.max(0, game.hurtFlash - dt * 1.6);
1067: }
1068: 
1069: function clampCamera() {
1070:   const zoom = game.cam.zoom;
1071:   const halfW = view.w / (2 * zoom);
1072:   const halfH = view.h / (2 * zoom);
1073:   if (WORLD_W > halfW * 2) game.cam.x = clamp(game.cam.x, halfW, WORLD_W - halfW);
1074:   else game.cam.x = WORLD_W / 2;
1075:   if (WORLD_H > halfH * 2) game.cam.y = clamp(game.cam.y, halfH, WORLD_H - halfH);
1076:   else game.cam.y = WORLD_H / 2;
1077: }
1078: 
1079: function updateTimers(dt) {
1080:   game.hintCd -= dt;
1081:   if (game.hintCd <= 0) {
1082:     game.hintCd = 0.35;
1083:     updateHint();
1084:   }
1085:   game.saveAt += dt;
1086:   if (game.saveAt > 8) {
1087:     game.saveAt = 0;
1088:     saveGame();
1089:   }
1090: }
