1092: // ————————————————————————————————————————————————
1093: // render
1094: // ————————————————————————————————————————————————
1095: 
1096: function render() {
1097:   ctx.setTransform(view.dpr, 0, 0, view.dpr, 0, 0);
1098:   ctx.clearRect(0, 0, view.w, view.h);
1099:   if (!game.player || game.state === 'title' || game.state === 'loading') {
1100:     ctx.fillStyle = '#f4ecd8';
1101:     ctx.fillRect(0, 0, view.w, view.h);
1102:     return;
1103:   }
1104: 
1105:   const cam = game.cam;
1106:   const w = view.w, h = view.h, zoom = cam.zoom;
1107:   const left = cam.x - w / (2 * zoom);
1108:   const top = cam.y - h / (2 * zoom);
1109:   const right = cam.x + w / (2 * zoom);
1110:   const bottom = cam.y + h / (2 * zoom);
1111: 
1112:   ctx.save();
1113:   ctx.translate(w / 2 + cam.sx, h / 2 + cam.sy);
1114:   ctx.scale(zoom, zoom);
1115:   ctx.translate(-cam.x, -cam.y);
1116: 
1117:   // painted biome canvases, over a wash that blends their feathered seams
1118:   const under = ctx.createLinearGradient(0, 0, WORLD_W, 0);
1119:   under.addColorStop(0, PALETTES.garden.paper);
1120:   under.addColorStop(0.125, PALETTES.garden.paper);
1121:   under.addColorStop(0.375, PALETTES.meadow.paper);
1122:   under.addColorStop(0.625, PALETTES.edge.paper);
1123:   under.addColorStop(0.875, PALETTES.deep.paper);
1124:   under.addColorStop(1, PALETTES.deep.paper);
1125:   ctx.fillStyle = under;
1126:   // only the feathered seams need the underlayer; the zone paintings are opaque elsewhere
1127:   for (const seam of [0, 1800, 3600, 5400, WORLD_W]) {
1128:     if (seam + 150 < left || seam - 150 > right) continue;
1129:     const x0 = Math.max(0, seam - 150);
1130:     const x1 = Math.min(WORLD_W, seam + 150);
1131:     ctx.fillRect(x0, 0, x1 - x0, WORLD_H);
1132:   }
1133: 
1134:   for (let i = 0; i < ZONES.length; i++) {
1135:     const z = ZONES[i];
1136:     if (z.x1 < left - 4 || z.x0 > right + 4) continue;
1137:     let art = zoneArt[i];
1138:     if (!art) art = zoneArt[i] = paintZoneCanvas(z);
1139:     ctx.drawImage(art, z.x0, 0, z.x1 - z.x0, WORLD_H);
1140:   }
1141: 
1142:   // still water
1143:   for (const pd of game.puddles) {
1144:     if (pd.x + pd.rx * 1.6 < left || pd.x - pd.rx * 1.6 > right) continue;
1145:     if (pd.y + pd.ry * 1.6 < top || pd.y - pd.ry * 1.6 > bottom) continue;
1146:     drawPuddle(ctx, pd, game.time, pd.drinking);
1147:   }
1148: 
1149:   drawBarriers(ctx, left, right);
1150: 
1151:   // living things, sorted into the depth of the painting
1152:   const drawList = [];
1153:   for (const f of game.flowers) {
1154:     if (f.x < left - 60 || f.x > right + 60 || f.y < top - 60 || f.y > bottom + 60) continue;
1155:     drawList.push({ y: f.y, kind: 'flower', obj: f });
1156:   }
1157:   for (const c of game.mobs) {
1158:     if (!c.alive) continue;
1159:     if (c.x < left - 120 || c.x > right + 120 || c.y < top - 120 || c.y > bottom + 120) continue;
1160:     drawList.push({ y: c.y + (c.sleeping ? -2 : 0), kind: 'critter', obj: c });
1161:   }
1162:   drawList.push({ y: game.player.y, kind: 'player', obj: game.player });
1163:   drawList.sort((a, b) => a.y - b.y);
1164:   for (const item of drawList) {
1165:     if (item.kind === 'flower') drawFlower(ctx, item.obj, game.time);
1166:     else if (item.kind === 'critter') drawCritter(ctx, item.obj, game.time);
1167:     else drawPlayer(ctx, item.obj, game.time);
1168:   }
1169: 
1170:   drawMotesWorld(ctx, left, top, right, bottom);
1171:   drawParticles(ctx);
1172:   drawFloatingText(ctx);
1173: 
1174:   ctx.restore();
1175: 
1176:   drawAtmosphere(ctx);
1177:   drawVignette(ctx);
1178: }
1179: 
1180: function drawBarriers(ctx, left, right) {
1181:   for (let bi = 0; bi < BARRIERS.length; bi++) {
1182:     const b = BARRIERS[bi];
1183:     if (b.x < left - 110 || b.x > right + 110) continue;
1184:     const locked = game.stage < b.require;
1185:     const P = PALETTES[ZONES[bi + 1].palette];
1186:     const rnd = mulberry32(910 + bi * 73);
1187:     const gapHalf = locked ? 0 : 210;
