function unlockText(w){const r=requirement(w);return r.boss?`Llega a oleada ${r.wave} y derrota ${r.boss} jefe${r.boss>1?'s':''}`:`Llega a oleada ${r.wave} y derrota ${r.kills} enemigos`}
function canUnlock(w){const r=requirement(w);return game.sessionWave>=r.wave&&game.runKills>=r.kills&&game.bossKills>=r.boss}
function checkUnlocks(){let newly=[];for(const w of weapons){if(w.unlock>0&&!save.unlocked?.includes(w.id)&&!game.owned.has(w.id)&&canUnlock(w)){save.unlocked=[...(save.unlocked||[]),w.id];newly.push(w)}}if(newly.length){newly.forEach(w=>game.notified.add(w.id));try{localStorage.setItem(SAVE_KEY,JSON.stringify({...save,record:Math.max(save.record||0,game.sessionWave)}))}catch(_){}toast(`¡Logro! ${newly[0].name} ya está disponible`);if(game.mode==='shop')renderShop()}}
function renderShop(){ui.shopCoins.textContent=game.coins;ui.unlockCount.textContent=String(weapons.filter(w=>w.unlock>0&&(save.unlocked||[]).includes(w.id)).length);document.querySelectorAll('.shop-tab').forEach(t=>t.classList.toggle('active',t.dataset.tab===game.tab));if(game.tab==='upgrades')renderUpgrades();else if(game.tab==='weapons')renderWeapons();else renderAchievements();ui.equipped.innerHTML=`EQUIPADO <b>${weapon(game.equipped.melee).icon} ${weapon(game.equipped.melee).name}</b> · <b>${weapon(game.equipped.ranged).icon} ${weapon(game.equipped.ranged).name}</b>`}
function renderUpgrades(){ui.content.innerHTML='<p class="section-label">MEJORAS DE PARTIDA · CADA NIVEL APLICA DE INMEDIATO</p><div class="item-grid">'+upgradeDefs.map(d=>{const level=game.upgrades[d.id],cost=priceUpgrade(d),max=level>=d.max;return `<article class="shop-item"><div class="item-icon">${d.icon}</div><div class="item-info"><strong>${names[d.id]}</strong><p>${descriptions[d.id]}</p><small>NIVEL ${level}/${d.max}</small></div><button class="item-action" data-upgrade="${d.id}" ${max||game.coins<cost?'disabled':''}>${max?'MÁXIMO':`✿ ${cost}`}</button></article>`}).join('')+'</div>';
ui.content.querySelectorAll('[data-upgrade]').forEach(btn=>btn.addEventListener('click',()=>buyUpgrade(btn.dataset.upgrade)))}
function renderWeapons(){const group=(type,label)=>`<section class="weapon-group"><h3>${label}</h3><div class="weapon-list">${weapons.filter(w=>w.type===type).map(w=>weaponCard(w)).join('')}</div></section>`;ui.content.innerHTML=group('melee','✦ ARMAS CUERPO A CUERPO · 15')+group('ranged','✧ ARMAS A DISTANCIA · 20');ui.content.querySelectorAll('[data-buy]').forEach(b=>b.addEventListener('click',()=>buyWeapon(b.dataset.buy)));ui.content.querySelectorAll('[data-equip]').forEach(b=>b.addEventListener('click',()=>equipWeapon(b.dataset.equip)));ui.content.querySelectorAll('[data-evolve]').forEach(b=>b.addEventListener('click',()=>evolveWeapon(b.dataset.evolve)))}
function weaponCard(w){const owned=game.owned.has(w.id),unlocked=w.unlock===0||(save.unlocked||[]).includes(w.id),equipped=game.equipped[w.type]===w.id,level=game.levels[w.id]||1,cost=Math.round((w.type==='melee'?48:54)+Number(w.id.slice(1))*4),eCost=evoPrice(w);let action='';if(!unlocked)action=`<button class="item-action" disabled>LOGRO</button>`;else if(!owned)action=`<button class="item-action" data-buy="${w.id}" ${game.coins<cost?'disabled':''}>✿ ${cost}</button>`;else action=`<div class="weapon-actions"><button class="item-action ${equipped?'equipped':''}" data-equip="${w.id}">${equipped?'EQUIPADA':'EQUIPAR'}</button>${level<4?`<button class="item-action evolve-action" data-evolve="${w.id}" ${game.coins<eCost?'disabled':''}>IVL ${level} · ✿${eCost}</button>`:'<small class="max-level">MAX IV</small>'}</div>`;return `<article class="weapon-card ${unlocked?'':'locked'}"><div class="item-icon">${w.icon}</div><div class="item-info"><strong>${w.name}</strong><p>${w.desc}</p><small>${unlocked?(owned?`EVOLUCIÓN ${level}/4`:`${w.type==='melee'?'CUERPO A CUERPO':'A DISTANCIA'} · DISPONIBLE`):unlockText(w)}</small></div>${action}</article>`}
function renderAchievements(){const rows=weapons.filter(w=>w.unlock>0).map(w=>{const ok=(save.unlocked||[]).includes(w.id),r=requirement(w);const progress=Math.min(game.sessionWave,r.wave);const kills=Math.min(game.runKills,r.kills);const boss=Math.min(game.bossKills,r.boss);return `<article class="achievement ${ok?'done':''}"><strong>${ok?'✦':'◇'} ${w.name}</strong><p>${unlockText(w)}</p><small>${ok?'DESBLOQUEADA':`OLEADA ${progress}/${r.wave} · BAJAS ${kills}/${r.kills}${r.boss?` · JEFES ${boss}/${r.boss}`:''}`}</small></article>`}).join('');ui.content.innerHTML='<p class="section-label">LOGROS DE PARTIDA · DESBLOQUEA ARMAS PARA FUTURAS PARTIDAS</p><div class="achievement-grid">'+rows+'</div>'}
function buyUpgrade(id){const d=upgradeDefs.find(x=>x.id===id),cost=priceUpgrade(d);if(!d||game.coins<cost||game.upgrades[id]>=d.max)return;game.coins-=cost;game.upgrades[id]++;if(id==='vitality'){game.player.maxHp+=18;game.player.hp=Math.min(game.player.maxHp,game.player.hp+34)}renderShop();updateHUD()}
function buyWeapon(id){const w=weapon(id),cost=Math.round((w.type==='melee'?48:54)+Number(w.id.slice(1))*4);if(!save.unlocked?.includes(id)&&w.unlock>0||game.coins<cost||game.owned.has(id))return;game.coins-=cost;game.owned.add(id);game.equipped[w.type]=id;renderShop();renderBadges();toast(`${w.name} añadida al arsenal`)}
function equipWeapon(id){const w=weapon(id);if(!game.owned.has(id))return;game.equipped[w.type]=id;renderShop();renderBadges();toast(`${w.name} equipada`)}
function evolveWeapon(id){const w=weapon(id),cost=evoPrice(w),level=game.levels[id];if(!game.owned.has(id)||level>=4||game.coins<cost)return;game.coins-=cost;game.levels[id]++;renderShop();renderBadges();toast(`${w.name} evolucionó a nivel ${game.levels[id]}`)}
function startBoss(){if(game.boss||game.bossSpawned||game.wave%10!==0)return;game.bossSpawned=true;const tier=game.wave/10;game.boss={x:game.w/2+(Math.random()-.5)*140,y:-55,r:38+tier*5,hp:360+tier*260,maxHp:360+tier*260,speed:30+tier*4,damage:16+tier*4,name:['','La reina de las zarzas','El ciervo de hollín','Corazón del jardín'][tier],attack:2.5,flash:0};game.effects.push({kind:'ring',x:game.w/2,y:game.h/2,r:6,max:110,time:.9,color:'#e9a16d'});toast(`¡JEFE! ${game.boss.name}`)}
function spawnEnemy(){if(game.enemies.length>28)return;const edge=Math.floor(Math.random()*4),pad=28;let x,y;if(edge===0){x=Math.random()*game.w;y=-pad}else if(edge===1){x=game.w+pad;y=Math.random()*game.h}else if(edge===2){x=Math.random()*game.w;y=game.h+pad}else{x=-pad;y=Math.random()*game.h}const rank=Math.min(5,Math.floor((game.wave-1)/5));const roll=Math.random();let kind=roll<.58?'mite':roll<.82?'beetle':roll<.94?'moth':'thorn';const stats={mite:[14,30,8,'#d7a85e'],beetle:[34,17,13,'#c67562'],moth:[21,24,7,'#ad9ed1'],thorn:[48,12,17,'#88ae62']}[kind];const hp=stats[0]*(1+game.wave*.095);game.enemies.push({id:++game.enemyId,x,y,r:stats[1]*(.77+rank*.045),hp,maxHp:hp,speed:stats[2]*(1+game.wave*.025),kind,color:stats[3],damage:8+game.wave*.62,phase:Math.random()*6,flash:0})}
function nearestTarget(x,y,range){let best=null,bestD=range*range;for(const e of game.enemies){const d=(e.x-x)**2+(e.y-y)**2;if(d<bestD){best=e;bestD=d}}if(game.boss){const d=(game.boss.x-x)**2+(game.boss.y-y)**2;if(d<bestD){best=game.boss;bestD=d}}return best}
function weaponStats(w){const level=game.levels[w.id]||1;return{damage:w.damage*Math.pow(1.34,level-1)*(1+game.upgrades.power*.22),rate:Math.max(.18,w.rate*Math.pow(.91,level-1)/(1+game.upgrades.haste*.12)),range:w.reach*(1+level*.045)}}
function autoAttack(dt){for(const type of ['melee','ranged']){const w=weapon(game.equipped[type]),stats=weaponStats(w);game.timers[type]=(game.timers[type]||0)-dt;if(game.timers[type]>0)continue;const target=nearestTarget(game.player.x,game.player.y,stats.range);if(!target)continue;game.timers[type]=stats.rate;if(type==='melee'){const angle=Math.atan2(target.y-game.player.y,target.x-game.player.x);const n=game.levels[w.id]>=3?2:1;let hits=0;for(const e of [...game.enemies,...(game.boss?[game.boss]:[])]){if(Math.hypot(e.x-game.player.x,e.y-game.player.y)<stats.range&&(hits<n)){dealDamage(e,stats.damage,w);hits++}}game.effects.push({kind:'slash',x:game.player.x,y:game.player.y,angle,r:stats.range,time:.22,max:.22,color:game.levels[w.id]>=4?'#d7ee86':'#d4dbaa'});if(!hits)dealDamage(target,stats.damage,w)}else{const angle=Math.atan2(target.y-game.player.y,target.x-game.player.x),speed=420+game.levels[w.id]*30;game.shots.push({x:game.player.x,y:game.player.y,vx:Math.cos(angle)*speed,vy:Math.sin(angle)*speed,r:5+game.levels[w.id],damage:stats.damage,target,life:stats.range/speed,color:game.levels[w.id]>=4?'#e6ce78':'#c8f078',weapon:w})}}}
function dealDamage(target,amount,w){if(!target)return;target.hp-=amount;target.flash=.12;game.effects.push({kind:'spark',x:target.x+(Math.random()-.5)*12,y:target.y+(Math.random()-.5)*12,r:3,time:.22,max:.22,color:w&&game.levels[w.id]>=4?'#f2db83':'#e7ecc8'});if(target.hp<=0){if(target===game.boss){game.boss=null;game.bossKills++;game.coins+=Math.round(75*(1+game.upgrades.fortune*.18));game.effects.push({kind:'ring',x:target.x,y:target.y,r:12,max:170,time:.7,color:'#e9cf73'});toast('¡Jefe derrotado! + monedas');checkUnlocks();updateHUD()}else{const i=game.enemies.indexOf(target);if(i>=0)game.enemies.splice(i,1);game.kills++;game.runKills++;const value=Math.max(2,Math.round((target.kind==='beetle'?5:target.kind==='thorn'?6:target.kind==='moth'?4:3)*(1+game.upgrades.fortune*.2)));game.drops.push({x:target.x,y:target.y,value,r:5,life:10,phase:Math.random()*5});if(game.upgrades.thorns>0&&Math.random()<.25){}if(game.runKills%4===0)checkUnlocks()}}}
function hurtPlayer(amount){const p=game.player;if(p.invuln>0)return;p.hp-=amount;p.invuln=.72;game.effects.push({kind:'ring',x:p.x,y:p.y,r:12,max:70,time:.35,color:'#f08b75'});if(game.upgrades.thorns){const attacker=nearestTarget(p.x,p.y,110);if(attacker)dealDamage(attacker,game.upgrades.thorns*7,null)}if(p.hp<=0){p.hp=0;finishRun(false,'La maleza ha cubierto el claro. Cada partida deja nuevas semillas.') }}
function update(dt){if(game.mode!=='combat')return;const p=game.player;game.elapsed+=dt;p.invuln=Math.max(0,p.invuln-dt);if(game.wave%10===0&&!game.bossSpawned&&game.timeLeft<19)startBoss();game.timeLeft-=dt;game.spawn-=dt;if(game.spawn<=0){spawnEnemy();game.spawn=Math.max(.31,1.22-game.wave*.021)*(.65+Math.random()*.7)}
let dx=0,dy=0;if(game.pointer){dx=game.pointer.x-game.pointer.startX;dy=game.pointer.y-game.pointer.startY;const len=Math.hypot(dx,dy);if(len>8){const power=Math.min(1,(len-8)/55);dx=dx/len*power;dy=dy/len*power}else{dx=dy=0}}else{if(game.keys.a||game.keys.arrowleft)dx-=1;if(game.keys.d||game.keys.arrowright)dx+=1;if(game.keys.w||game.keys.arrowup)dy-=1;if(game.keys.s||game.keys.arrowdown)dy+=1;const l=Math.hypot(dx,dy)||1;dx/=l;dy/=l}const speed=205*(1+game.upgrades.stride*.1);p.x=Math.max(26,Math.min(game.w-26,p.x+dx*speed*dt));p.y=Math.max(78,Math.min(game.h-25,p.y+dy*speed*dt));if(Math.abs(dx)+Math.abs(dy)>.05)p.walk+=dt*10;
for(const e of game.enemies){const angle=Math.atan2(p.y-e.y,p.x-e.x),wiggle=Math.sin(game.elapsed*2+e.phase)*.18;e.x+=(Math.cos(angle+wiggle)*e.speed)*dt;e.y+=(Math.sin(angle+wiggle)*e.speed)*dt;e.flash=Math.max(0,e.flash-dt);if(Math.hypot(e.x-p.x,e.y-p.y)<e.r+p.r)hurtPlayer(e.damage*dt*1.6)}
if(game.boss){const b=game.boss;const a=Math.atan2(p.y-b.y,p.x-b.x);b.x+=(Math.cos(a)*b.speed+Math.sin(game.elapsed)*15)*dt;b.y+=(Math.sin(a)*b.speed+Math.cos(game.elapsed*.7)*8)*dt;b.attack-=dt;b.flash=Math.max(0,b.flash-dt);if(Math.hypot(b.x-p.x,b.y-p.y)<b.r+p.r)hurtPlayer(b.damage*dt);if(b.attack<=0){b.attack=2.2;const angle=Math.atan2(p.y-b.y,p.x-b.x);game.shots.push({x:b.x,y:b.y,vx:Math.cos(angle)*145,vy:Math.sin(angle)*145,r:8,damage:b.damage*.55,life:4,enemy:true,color:'#f29b73'})}}
autoAttack(dt);for(let i=game.shots.length-1;i>=0;i--){const s=game.shots[i];s.life-=dt;if(s.target&&!s.enemy&&(game.enemies.includes(s.target)||s.target===game.boss)){const a=Math.atan2(s.target.y-s.y,s.target.x-s.x),sp=Math.hypot(s.vx,s.vy);s.vx+=(Math.cos(a)*sp-s.vx)*Math.min(1,dt*3);s.vy+=(Math.sin(a)*sp-s.vy)*Math.min(1,dt*3)}s.x+=s.vx*dt;s.y+=s.vy*dt;let hit=false;if(s.enemy){if(Math.hypot(s.x-p.x,s.y-p.y)<p.r+s.r){hurtPlayer(s.damage);hit=true}}else{for(const e of [...game.enemies,...(game.boss?[game.boss]:[])])if(Math.hypot(s.x-e.x,s.y-e.y)<e.r+s.r){dealDamage(e,s.damage,s.weapon);hit=true;break}}if(hit||s.life<=0||s.x<-40||s.x>game.w+40||s.y<-40||s.y>game.h+40)game.shots.splice(i,1)}
const magnet=62+game.upgrades.magnet*42;for(let i=game.drops.length-1;i>=0;i--){const d=game.drops[i];d.life-=dt;const dist=Math.hypot(p.x-d.x,p.y-d.y);if(dist<magnet){const a=Math.atan2(p.y-d.y,p.x-d.x);d.x+=Math.cos(a)*(180+magnet)*dt;d.y+=Math.sin(a)*(180+magnet)*dt}if(dist<p.r+15){game.coins+=d.value;game.drops.splice(i,1);updateHUD()}else if(d.life<=0)game.drops.splice(i,1)}
for(let i=game.effects.length-1;i>=0;i--){const e=game.effects[i];e.time-=dt;if(e.kind==='ring')e.r+=(e.max-e.r)*dt*7;if(e.time<=0)game.effects.splice(i,1)}if(game.upgrades.companion){game.companionAngle+=dt*1.8;const t=nearestTarget(p.x,p.y,480);game.timers.companion=(game.timers.companion||0)-dt;if(t&&game.timers.companion<=0){game.timers.companion=.72;const a=Math.atan2(t.y-p.y,t.x-p.x);game.shots.push({x:p.x+Math.cos(game.companionAngle)*27,y:p.y+Math.sin(game.companionAngle)*27,vx:Math.cos(a)*400,vy:Math.sin(a)*400,r:5,damage:17*(1+game.upgrades.power*.15),target:t,life:1.5,color:'#9ee5ad'})}}
if(game.timeLeft<=0){game.timeLeft=0;if(game.wave%10===0&&game.boss){if(game.phase!=='boss'){game.phase='boss';ui.phase.textContent='JEFE · TIEMPO EXTRA';toast('El jefe sigue en pie. ¡Derrota al guardián!')}}else completeWave()}updateHUD()}
function completeWave(){if(game.mode!=='combat')return;game.sessionWave=Math.max(game.sessionWave,game.wave);game.coins+=15+Math.floor(game.wave*1.6);if(game.wave>=30){finishRun(true,'Los tres guardianes han caído. El jardín vuelve a florecer.');return}game.wave++;game.enemies=[];game.shots=game.shots.filter(s=>s.enemy);game.drops=[];checkUnlocks();openShop(false)}
function finishRun(won,message){if(game.mode==='result')return;game.mode='result';game.pointer=null;game.sessionWave=Math.max(game.sessionWave,won?30:Math.max(0,game.wave-1));saveProgress();hideScreens();ui.hud.hidden=true;ui.badges.hidden=true;ui.pause.hidden=true;const kicker=$('result-kicker'),title=$('result-title'),copy=$('result-copy');kicker.textContent=won?'EL JARDÍN RECUERDA':'LA NATURALEZA RECUERDA';title.textContent=won?'¡Victoria!':'La partida termina';copy.textContent=message;$('result-stats').innerHTML=`<div><b>${game.sessionWave}</b><small>OLEADAS</small></div><div><b>${game.runKills}</b><small>BAJAS</small></div><div><b>${game.bossKills}</b><small>JEFES</small></div>`;const fresh=weapons.filter(w=>w.unlock>0&&game.notified.has(w.id));$('result-unlocks').innerHTML=fresh.length?`<div class="unlock-notice">Nuevas armas disponibles: <b>${fresh.map(w=>w.name).join(' · ')}</b></div>`:'';ui.record.textContent=`RÉCORD: OLEADA ${save.record||0}`;ui.result.hidden=false}
function renderBadges(){ui.badges.innerHTML=['melee','ranged'].map(type=>{const w=weapon(game.equipped[type]);return `<div class="weapon-badge"><i>${w.icon}</i><span>${w.name}</span><small>IVL ${game.levels[w.id]||1}</small></div>`}).join('')}
function drawBackground(){const w=game.w,h=game.h;const g=ctx.createLinearGradient(0,0,w,h);g.addColorStop(0,'#1a2a20');g.addColorStop(.55,'#14231a');g.addColorStop(1,'#101c16');ctx.fillStyle=g;ctx.fillRect(0,0,w,h);ctx.save();ctx.globalAlpha=.16;ctx.strokeStyle='#8caa75';ctx.lineWidth=1;const spacing=58;for(let x=14;x<w;x+=spacing){ctx.beginPath();ctx.moveTo(x,75);ctx.bezierCurveTo(x+Math.sin(x)*14,h*.35,x-Math.cos(x)*20,h*.7,x+Math.sin(x*.2)*15,h);ctx.stroke()}for(let i=0;i<38;i++){const x=((i*173+37)%Math.max(1,w)),y=90+((i*239+19)%Math.max(1,h-110));ctx.fillStyle=i%3?'#8aa16b':'#c6c982';ctx.beginPath();ctx.ellipse(x,y,2+(i%3),1.4,Math.sin(i)*2,0,Math.PI*2);ctx.fill()}ctx.restore();const glow=ctx.createRadialGradient(w*.5,h*.48,5,w*.5,h*.48,Math.min(w,h)*.53);glow.addColorStop(0,'#c6e67a0b');glow.addColorStop(1,'#08120d00');ctx.fillStyle=glow;ctx.fillRect(0,0,w,h)}
